from pathlib import Path
from zipfile import ZipFile, ZIP_DEFLATED
from copy import deepcopy
from lxml import etree as E
R=Path(__file__).resolve().parent
REF=R/'말마프렌즈_온라인스토어_추가개발_견적서_v13.docx'
with ZipFile(REF) as z: parts={n:z.read(n) for n in z.namelist()}
N={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}; W='{'+N['w']+'}'
x=E.fromstring(parts['word/document.xml']); body=x.find('w:body',N)
ps=body.findall('w:p',N); tabs=body.findall('w:tbl',N)
def setp(p,s):
 pr=p.find('w:pPr',N); r=p.find('w:r',N)
 rp=deepcopy(r.find('w:rPr',N)) if r is not None and r.find('w:rPr',N) is not None else None
 for e in list(p):
  if e is not pr:p.remove(e)
 r=E.SubElement(p,W+'r')
 if rp is not None:r.append(rp)
 E.SubElement(r,W+'t').text=s
def replace(prefix,s):
 m=[p for p in ps if ''.join(p.xpath('.//w:t/text()',namespaces=N)).startswith(prefix)]
 assert len(m)==1,prefix
 setp(m[0],s)
def t(n,rows):
 tab=tabs[n]; orig=tab.findall('w:tr',N)
 for r in orig:tab.remove(r)
 for i,row in enumerate(rows):
  r=deepcopy(orig[0] if i==0 else orig[-1] if i==len(rows)-1 else orig[min(i,len(orig)-2)])
  cells=r.findall('w:tc',N); assert len(cells)==len(row)
  for c,s in zip(cells,row):
   pp=c.findall('w:p',N)
   for e in pp[1:]:c.remove(e)
   setp(pp[0],s)
  tab.append(r)
